import gzip
from html import escape
from format_lecon import R,paras
def quote(n,s):
 original=gzip.open(R/f'ressources_ia/aips/fi_fr/{n}.txt.gz','rt').read()
 assert s in original,(n,s)
 return '<blockquote><p>« '+escape(s)+' »</p></blockquote>'
def grossesse(n):
 textes={
 '33043':["Mycostatine ne peut être utilisé pendant la grossesse que si le médicament est absolument nécessaire.","Mycostatine ne peut être utilisé pendant l'allaitement que si le médicament est absolument nécessaire."],
 '55901':["Salagen ne doit être utilisé pendant la grossesse que si le bénéfice escompté l'emporte sur les risques éventuels pour le fœtus.","La décision de renoncer à l'allaitement ou de renoncer au traitement par Salagen doit être prise en tenant compte du bénéfice de l'allaitement pour l'enfant et du bénéfice du traitement pour la mère."],
 '44911':["La prudence est donc de rigueur lors de l'emploi d'Amoxi-Mepha au cours de la grossesse.","La substance ne doit donc pas être administrée pendant la période d'allaitement ou, si nécessaire, il faut procéder au sevrage de l'enfant."],
 '45343':["Néanmoins, pendant la grossesse, le traitement intraveineux et oral n'est indiqué qu'en cas de nécessité impérieuse (voir aussi «Données précliniques»).","C'est pourquoi il ne faut pas utiliser Zovirax pendant l'allaitement."],
 '56758':["Co-Amoxi-Mepha i.v. ne devrait donc être utilisé pendant la grossesse qu'en cas de nécessité absolue.","Il ne faudrait donc pas allaiter pendant le traitement par Co-Amoxi-Mepha i.v."]}
 return paras('Grossesse et allaitement — extraits exacts de la notice de cette préparation :')+''.join(quote(n,t) for t in textes[n])+paras('Ces restrictions sont celles de la préparation citée. Faire vérifier le choix avec le prescripteur et le pharmacien, en recherchant une alternative appropriée si nécessaire ; ne pas interrompre seul un traitement essentiel ou l’allaitement.')
def amoxicilline(l):
 text=paras('Amoxi-Mepha, amoxicilline orale : l’indication inclut la pharyngite streptococcique. Les extraits suivants reproduisent l’information professionnelle suisse ; ils ne constituent pas une prescription automatique.')
 text+=quote('44911','La posologie dépend du mode d\'utilisation, de l\'âge, du poids corporel et de la fonction rénale du patient, de même que du degré de gravité de l\'infection et de la sensibilité du germe en cause.')
 text+=paras('Notice : adultes et enfants de plus de 40 kg, infections légères à moyennes.')+quote('44911',"Consignes générales: 1500 mg – 3000 mg d'amoxicilline/jour en 3 à 4 doses individuelles.")
 text+=paras('Notice : enfants jusqu’à 40 kg inclus.')+quote('44911',"Indications générales: 50 à 100 mg/kg/jour, répartis en 3 à 4 prises.")+quote('44911','Dose journalière maximale: 2000 mg répartis en 3 à 4 prises.')
 text+=quote('44911',"Lors d'infections dues aux streptocoques β-hémolytiques du groupe A, le traitement devrait durer au moins dix jours.")
 text+=paras('La directive SSI consultée recommande, si l’antibiotique est retenu, amoxicilline orale 1 g toutes les 12 heures pendant 6 jours chez l’adulte, et 25 mg/kg toutes les 12 heures pendant 6 jours chez l’enfant. Ce schéma de recommandation diffère de la notice citée par la répartition et la durée : ne pas le présenter comme un verbatim AIPS. Le prescripteur doit choisir et documenter le schéma applicable, son plafond pédiatrique et son adaptation rénale, avec le pharmacien si nécessaire.', 'Contre-indications de la préparation : hypersensibilité aux pénicillines ou céphalosporines, mononucléose infectieuse et leucémie lymphoïde. Une allergie rapportée doit être caractérisée ; une forme grave exclut une substitution empirique par une autre bêta-lactamine.', 'Vérifier fonction rénale, interactions, réaction cutanée, diarrhée sévère et hydratation. Une infection compliquée ne se traite pas avec ce seul schéma ambulatoire.')
 text+=grossesse('44911')
 return l.subwindow('amoxi','Amoxicilline : notice suisse et recommandation SSI',text,(3,4,19))
def nystatine(l):
 text=paras('Mycostatine Suspension, nystatine 100 000 unités internationales par ml, voie buccale ou orale. Pour une candidose buccale, les extraits de la notice suisse sont :')
 text+=quote('33043',"· Candidoses de la cavité buccale et de l'œsophage: 1 ml (100'000 U.I.) 4 fois par jour. Cette dose peut être augmentée si nécessaire.")
 text+=quote('33043','Afin de prévenir les récidives, le traitement doit être poursuivi 48 heures au moins après la guérison clinique.')
 text+=quote('33043',"L'administration se fera à distance des repas.")
 text+=quote('33043','Lors de candidoses buccales, la suspension doit être retenue dans la bouche aussi longtemps que possible et être répartie avec la langue dans la cavité buccale entière. Le reste sera avalé.')
 text+=paras('La notice mentionne des schémas néonataux, mais sa rubrique des excipients impose la restriction suivante, à respecter pour cette préparation :')+quote('33043','Ce médicament ne doit pas être utilisé chez les nouveau-nés (moins de 4 semaines).')
 text+=quote('33043',"Ne pas utiliser pendant plus d'une semaine chez les jeunes enfants (moins de 3 ans) en raison de l'accumulation.")
 text+=paras('Ne pas transposer les anciennes indications néonatales sans avis pédiatrique et pharmaceutique sur une préparation appropriée. La notice déconseille également cette suspension chez les prématurés ou en cas d’insuffisance pondérale sévère.', 'Contre-indication : hypersensibilité à la nystatine ou à un composant. Vérifier les intolérances héréditaires aux sucres et les excipients ; interrompre devant une réaction cutanée grave ou une hypersensibilité.', 'La nystatine n’a pas d’effet sur les candidoses systémiques. Malgré la mention de l’œsophage dans la notice, une suspicion de candidose œsophagienne, surtout en immunodépression, exige un bilan et une stratégie systémique spécialisée, plutôt qu’une simple reconduction du traitement local.')
 text+=quote('33043','Hypersensibilité à la nystatine ou à un des autres composants.')+grossesse('33043')
 return l.subwindow('nystatine','Nystatine : dose, administration et restrictions de la préparation',text,(17,23,24))
def aciclovir(l):
 text=paras('Zovirax comprimés ou suspension, aciclovir oral : schéma de la notice pour adultes et enfants de plus de 12 ans, infections cutanéo-muqueuses à Herpes simplex, immunocompétents et à fonction rénale normale.')
 text+=quote('45343','200 mg 5 fois par jour, toutes les 4 heures (pause nocturne de 8 heures).')+quote('45343','Durée du traitement: 5 jours et plus.')
 text+=quote('45343',"Il est recommandé d'entreprendre le traitement précocement, si possible dès le stade des prodromes.")
 text+=quote('45343',"La suspension ne doit pas être diluée. L'emballage contient une mesurette servant à mesurer les doses de 400 mg (5 ml) et de 200 mg (2,5 ml). En cas de prescription de doses de 100 mg, il est recommandé de remettre au patient une mesurette adaptée ou une seringue graduée pour prise orale permettant de mesurer 1,25 ml.")
 text+=paras('Le choix d’un antiviral se discute surtout si infection sévère, persistante ou terrain à risque. Chez l’enfant, le schéma doit être validé selon âge, poids, gravité et préparation ; ne pas extrapoler une posologie adulte à un nourrisson. Une forme néonatale, disséminée, neurologique ou ne permettant pas la voie orale relève d’une prise en charge hospitalière.', 'La notice adapte le schéma oral de 200 mg cinq fois par jour à 200 mg toutes les 12 heures si la clairance de la créatinine est inférieure à 10 ml/min. Vérifier fonction rénale et hydratation ; surveiller les effets neurologiques, surtout chez la personne âgée ou insuffisante rénale.', 'Contre-indications : hypersensibilité à l’aciclovir, au valaciclovir ou aux excipients. La suspension contient notamment sorbitol et traces d’alcool benzylique : pas chez le nouveau-né, pas au-delà d’une semaine avant trois ans, et pas en cas d’intolérance héréditaire au fructose. Une crème destinée à la lèvre ne remplace pas un traitement d’atteinte buccale diffuse.')
 text+=paras('Rubrique pédiatrique de la notice pour Herpes simplex et prévention chez les immunodéprimés :')+quote('45343',">2 ans: dose de l'adulte.\n<2 ans: la moitié de la dose de l'adulte.\nNouveau-nés: voir administration i.v.")
 text+=paras('Les bornes sont reproduites telles qu’écrites ; l’âge exact de deux ans et toute situation pédiatrique complexe demandent une vérification prescripteur/pharmacien. Tenir compte des restrictions de la suspension et ne pas extrapoler ces lignes à l’herpès néonatal.')+grossesse('45343')
 return l.subwindow('aciclovir','Aciclovir oral : schéma suisse et précautions',text,(16,20))
def pilocarpine(l):
 text=paras('Salagen, chlorhydrate de pilocarpine, comprimés de 5 mg par voie orale. L’information suisse distingue xérostomie grave après radiothérapie ORL et xérostomie liée à Sjögren ; elle ne couvre pas toute sécheresse médicamenteuse.')
 text+=paras('Sjögren :')+quote('55901','Adultes: 5 mg (1 comprimé pelliculé) 4 fois par jour.')
 text+=quote('55901',"Une durée de traitement de 6 semaines est nécessaire pour atteindre un effet thérapeutique complet. Le traitement doit être interrompu si aucune amélioration de la xérostomie n'est visible après 2 à 3 mois.")
 text+=paras('Après radiothérapie :')+quote('55901','Adultes: 5 mg (1 comprimé pelliculé) 3 fois par jour.')
 text+=quote('55901',"Avaler les comprimés pelliculés pendant ou immédiatement après les repas avec un verre d'eau.")
 text+=paras('L’effet dépend d’une fonction glandulaire résiduelle. Le schéma initial progressif décrit par certaines recommandations étrangères n’est pas présenté ici comme la posologie de la notice suisse.', 'Contre-indications notamment : asthme non maîtrisé, maladies cardiovasculaires ou rénales non maîtrisées, situations où les agonistes cholinergiques sont dangereux, dialyse avec clairance inférieure à 10 ml/min, et situations où le myosis n’est pas souhaitable. Vérifier la liste complète avant toute prescription.', 'Surveiller sueurs et déshydratation, bronchospasme, effets cardiaques et visuels ; prévoir les contrôles ophtalmiques mentionnés dans la notice. Prudence avec bêtabloquants, autres médicaments cholinergiques et anticholinergiques. En cas de cirrhose modérée à sévère, la notice recommande une dose journalière initiale réduite de moitié ; efficacité et sécurité pédiatriques non démontrées.')
 text+=quote('55901',"La sécurité et l'efficacité de ce médicament chez les enfants et les adolescents n'ont pas été démontrées.")+grossesse('55901')
 return l.subwindow('pilocarpine','Pilocarpine : deux indications et leurs doses suisses',text,(15,18))
def coamoxicilline(l):
 text=paras('Co-Amoxi-Mepha injectable/perfusion associe amoxicilline et acide clavulanique. Exemple de préparation suisse utilisable après décision hospitalière pour une infection sensible ; le choix doit couvrir la flore attendue, tenir compte des allergies et du protocole local. Le drainage reste essentiel pour l’abcès.')
 text+=paras('Extrait AIPS, adultes et enfants de plus de 40 kg, infections de gravité modérée :')+quote('56758','1200 mg (1000/200) 3-4 × par jour en injection intraveineuse lente.')
 text+=paras('Extrait AIPS, infections graves dans la même population :')+quote('56758','2200 mg (2000/200) 3-4 × par jour en perfusion brève (au moins 30 minutes).')
 text+=quote('56758',"La posologie dépend de l'âge, du poids et de la fonction rénale du patient, ainsi que du degré de sévérité de l'infection.Co-Amoxi-Mepha i.v. ne doit pas être administré plus souvent que toutes les 4 heures.")
 text+=paras('Les chiffres entre parenthèses désignent amoxicilline/acide clavulanique en mg. Ne pas confondre les ratios adultes et pédiatriques ni calculer une dose pédiatrique à partir de ce seul extrait. La fonction rénale nécessite un schéma d’adaptation spécifique avant prescription.', 'La durée de l’abcès n’est pas fixée par ces lignes AIPS : le protocole CHUV publié en 2021 décrit un relais oral selon l’évolution et une durée totale de 10 à 14 jours. Le protocole local actuel, le drainage, les cultures et la réponse clinique déterminent la décision.', 'Contre-indications : hypersensibilité connue aux pénicillines, céphalosporines ou à l’acide clavulanique, et antécédent d’ictère ou d’atteinte hépatique sous cette association. Surveiller réactions allergiques ou cutanées sévères, fonction rénale et tolérance hépatique ; vérifier les interactions et la préparation avant administration. Une allergie grave exige une alternative validée avec l’équipe, sans substitution automatique.')
 text+=quote('56758',"L'usage de Co-Amoxi-Mepha i.v. est contre-indiqué en cas d'hypersensibilité connue aux pénicillines et céphalosporines ou à l'acide clavulanique, de même que chez les patients qui ont présenté un ictère ou des troubles de la fonction hépatique pendant un traitement antérieur par Co-Amoxi-Mepha i.v.")+grossesse('56758')
 return l.subwindow('coamoxi','Amoxicilline–acide clavulanique : exemple hospitalier suisse',text,(26,27))
